begin;
drop policy if exists "profiles_select_visible" on public.profiles;
create policy "profiles_select_authenticated" on public.profiles for select to authenticated using (true);
drop policy if exists "sessions_select_own_or_coach" on public.athlete_sessions;
create policy "sessions_select_own_or_coach" on public.athlete_sessions for select to authenticated using (((athlete_id = ( SELECT auth.uid() AS uid)) OR is_group_coach(group_id) OR ((is_org_admin_of_group(group_id) OR is_platform_admin()) AND (NOT is_client_private_from_org(group_id, athlete_id)))));
drop policy if exists "coach_briefing_items_select_assigned_or_cascade" on public.coach_briefing_items;
create policy "coach_briefing_items_select_assigned_or_cascade" on public.coach_briefing_items for select to authenticated using ((is_group_coach(group_id) OR ((NOT is_client_private_from_org(group_id, athlete_id)) AND (is_org_admin_of_group(group_id) OR is_platform_admin()))));
drop policy if exists "gwes_select_members" on public.group_workout_exercise_sets;
create policy "gwes_select_members" on public.group_workout_exercise_sets for select to authenticated using ((EXISTS ( SELECT 1 FROM group_workout_exercises g WHERE ((g.id = group_workout_exercise_sets.group_workout_exercise_id) AND ((is_group_member(g.group_id) AND ((g.athlete_id IS NULL) OR (g.athlete_id = ( SELECT auth.uid() AS uid)) OR is_group_coach(g.group_id)) AND (is_group_coach(g.group_id) OR is_workout_visible_to_athlete(g.workout_id))) OR ((is_org_admin_of_group(g.group_id) OR is_platform_admin()) AND ((g.athlete_id IS NULL) OR (NOT is_client_private_from_org(g.group_id, g.athlete_id)))))))));
drop policy if exists "gwe_select_members" on public.group_workout_exercises;
create policy "gwe_select_members" on public.group_workout_exercises for select to authenticated using (((is_group_member(group_id) AND ((athlete_id IS NULL) OR (athlete_id = ( SELECT auth.uid() AS uid)) OR is_group_coach(group_id)) AND (is_group_coach(group_id) OR is_workout_visible_to_athlete(workout_id))) OR ((is_org_admin_of_group(group_id) OR is_platform_admin()) AND ((athlete_id IS NULL) OR (NOT is_client_private_from_org(group_id, athlete_id))))));
drop policy if exists "posts_select_members" on public.posts;
create policy "posts_select_members" on public.posts for select to authenticated using ((is_group_member(group_id) OR is_org_admin_of_group(group_id) OR is_platform_admin()));
drop policy if exists "posts_delete_own_or_coach" on public.posts;
create policy "posts_delete_own_or_coach" on public.posts for delete to authenticated using (((author_id = ( SELECT auth.uid() AS uid)) OR is_group_coach(group_id) OR is_org_admin_of_group(group_id) OR is_platform_admin()));
drop policy if exists "session_exercises_select_own_or_coach" on public.session_exercises;
create policy "session_exercises_select_own_or_coach" on public.session_exercises for select to authenticated using ((EXISTS ( SELECT 1 FROM athlete_sessions s WHERE ((s.id = session_exercises.session_id) AND ((s.athlete_id = ( SELECT auth.uid() AS uid)) OR is_group_coach(s.group_id) OR ((is_org_admin_of_group(s.group_id) OR is_platform_admin()) AND (NOT is_client_private_from_org(s.group_id, s.athlete_id))))))));
drop policy if exists "set_logs_select_own_or_coach" on public.set_logs;
create policy "set_logs_select_own_or_coach" on public.set_logs for select to authenticated using ((EXISTS ( SELECT 1 FROM (session_exercises se JOIN athlete_sessions s ON ((s.id = se.session_id))) WHERE ((se.id = set_logs.session_exercise_id) AND ((s.athlete_id = ( SELECT auth.uid() AS uid)) OR is_group_coach(s.group_id) OR ((is_org_admin_of_group(s.group_id) OR is_platform_admin()) AND (NOT is_client_private_from_org(s.group_id, s.athlete_id))))))));
drop policy if exists "wearable_connections_select_own_or_coach" on public.wearable_connections;
create policy "wearable_connections_select_own_or_coach" on public.wearable_connections for select to authenticated using ((profile_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1 FROM (group_memberships gm_self JOIN group_memberships gm_target ON ((gm_target.group_id = gm_self.group_id))) WHERE ((gm_self.profile_id = ( SELECT auth.uid() AS uid)) AND (gm_self.role = 'coach'::member_role) AND (gm_target.profile_id = wearable_connections.profile_id)))) OR ((NOT is_wearable_subject_private_from_org(profile_id)) AND ((EXISTS ( SELECT 1 FROM ((group_memberships gm_target JOIN groups g ON ((g.id = gm_target.group_id))) JOIN organization_memberships om ON ((om.organization_id = g.organization_id))) WHERE ((gm_target.profile_id = wearable_connections.profile_id) AND (om.profile_id = ( SELECT auth.uid() AS uid)) AND (om.role = ANY (ARRAY['owner'::org_member_role, 'admin'::org_member_role]))))) OR is_platform_admin())));
drop policy if exists "wearable_daily_metrics_select_own_or_coach" on public.wearable_daily_metrics;
create policy "wearable_daily_metrics_select_own_or_coach" on public.wearable_daily_metrics for select to authenticated using ((EXISTS ( SELECT 1 FROM wearable_connections c WHERE ((c.id = wearable_daily_metrics.connection_id) AND ((c.profile_id = ( SELECT auth.uid() AS uid)) OR (EXISTS ( SELECT 1 FROM (group_memberships gm_self JOIN group_memberships gm_target ON ((gm_target.group_id = gm_self.group_id))) WHERE ((gm_self.profile_id = ( SELECT auth.uid() AS uid)) AND (gm_self.role = 'coach'::member_role) AND (gm_target.profile_id = c.profile_id)))) OR ((NOT is_wearable_subject_private_from_org(c.profile_id)) AND ((EXISTS ( SELECT 1 FROM ((group_memberships gm_target JOIN groups g ON ((g.id = gm_target.group_id))) JOIN organization_memberships om ON ((om.organization_id = g.organization_id))) WHERE ((gm_target.profile_id = c.profile_id) AND (om.profile_id = ( SELECT auth.uid() AS uid)) AND (om.role = ANY (ARRAY['owner'::org_member_role, 'admin'::org_member_role]))))) OR is_platform_admin())))))));
drop policy if exists "client_tag_assignments_select_org_member" on public.client_tag_assignments;
